-- Closes the gap between this app's Cars attribute set (10 fields: make/model/year/mileage/fuel/
-- transmission/colour/condition/brand/power) and Marktplaats.nl's real car-listing form (captured
-- live 2026-09-18): body type, emission class, interior, upholstery, curb weight, cylinder count,
-- engine displacement, braked/unbraked towing capacity, maintenance/VAT booleans, and the big
-- "Opties" feature checklist. Only possible now that multi_select and boolean are real, supported
-- data types (lib/categories.ts's SUPPORTED_DATA_TYPES, components/listing-attribute-field.tsx) --
-- this migration is pure data, no further app code changes needed for any of it to render/save.
BEGIN;

-- New single_select/integer attributes.
INSERT INTO attributes(stable_key,data_type,unit_code) VALUES('body_type','single_select',NULL) ON CONFLICT(stable_key) DO NOTHING;
INSERT INTO attribute_translations(attribute_id,language_code,name) SELECT id,'en','Body Type' FROM attributes WHERE stable_key='body_type' ON CONFLICT DO NOTHING;
INSERT INTO attributes(stable_key,data_type,unit_code) VALUES('emission_class','single_select',NULL) ON CONFLICT(stable_key) DO NOTHING;
INSERT INTO attribute_translations(attribute_id,language_code,name) SELECT id,'en','Emission Class' FROM attributes WHERE stable_key='emission_class' ON CONFLICT DO NOTHING;
INSERT INTO attributes(stable_key,data_type,unit_code) VALUES('interior_type','single_select',NULL) ON CONFLICT(stable_key) DO NOTHING;
INSERT INTO attribute_translations(attribute_id,language_code,name) SELECT id,'en','Interior' FROM attributes WHERE stable_key='interior_type' ON CONFLICT DO NOTHING;
INSERT INTO attributes(stable_key,data_type,unit_code) VALUES('upholstery','single_select',NULL) ON CONFLICT(stable_key) DO NOTHING;
INSERT INTO attribute_translations(attribute_id,language_code,name) SELECT id,'en','Upholstery' FROM attributes WHERE stable_key='upholstery' ON CONFLICT DO NOTHING;
INSERT INTO attributes(stable_key,data_type,unit_code) VALUES('curb_weight','integer','kg') ON CONFLICT(stable_key) DO NOTHING;
INSERT INTO attribute_translations(attribute_id,language_code,name) SELECT id,'en','Curb Weight' FROM attributes WHERE stable_key='curb_weight' ON CONFLICT DO NOTHING;
INSERT INTO attributes(stable_key,data_type,unit_code) VALUES('cylinder_count','integer',NULL) ON CONFLICT(stable_key) DO NOTHING;
INSERT INTO attribute_translations(attribute_id,language_code,name) SELECT id,'en','Cylinders' FROM attributes WHERE stable_key='cylinder_count' ON CONFLICT DO NOTHING;
INSERT INTO attributes(stable_key,data_type,unit_code) VALUES('engine_displacement','integer','cc') ON CONFLICT(stable_key) DO NOTHING;
INSERT INTO attribute_translations(attribute_id,language_code,name) SELECT id,'en','Engine Displacement' FROM attributes WHERE stable_key='engine_displacement' ON CONFLICT DO NOTHING;
INSERT INTO attributes(stable_key,data_type,unit_code) VALUES('towing_capacity_braked','integer','kg') ON CONFLICT(stable_key) DO NOTHING;
INSERT INTO attribute_translations(attribute_id,language_code,name) SELECT id,'en','Towing Capacity (Braked)' FROM attributes WHERE stable_key='towing_capacity_braked' ON CONFLICT DO NOTHING;
INSERT INTO attributes(stable_key,data_type,unit_code) VALUES('towing_capacity_unbraked','integer','kg') ON CONFLICT(stable_key) DO NOTHING;
INSERT INTO attribute_translations(attribute_id,language_code,name) SELECT id,'en','Towing Capacity (Unbraked)' FROM attributes WHERE stable_key='towing_capacity_unbraked' ON CONFLICT DO NOTHING;

-- New boolean attributes (Onderhoud/BTW section).
INSERT INTO attributes(stable_key,data_type,unit_code) VALUES('dealer_maintained','boolean',NULL) ON CONFLICT(stable_key) DO NOTHING;
INSERT INTO attribute_translations(attribute_id,language_code,name) SELECT id,'en','Dealer Maintained' FROM attributes WHERE stable_key='dealer_maintained' ON CONFLICT DO NOTHING;
INSERT INTO attributes(stable_key,data_type,unit_code) VALUES('maintenance_booklet','boolean',NULL) ON CONFLICT(stable_key) DO NOTHING;
INSERT INTO attribute_translations(attribute_id,language_code,name) SELECT id,'en','Maintenance Booklet' FROM attributes WHERE stable_key='maintenance_booklet' ON CONFLICT DO NOTHING;
