INSERT INTO category_attributes(category_id,attribute_id,is_required,is_search_filter) SELECT c.id,a.id,false,true FROM categories c,attributes a WHERE c.stable_key='cars' AND a.stable_key='body_type' ON CONFLICT DO NOTHING;
